<script setup lang="ts">
interface Supplier { id: string; code: string; name: string }
interface LedgerRow { id: string; entryDate: string; voucherNo: string; purchaseNo: string | null; particulars: string | null; debit: string; credit: string; paymentMode: string | null; referenceNo: string | null; dueDate: string | null; status: string; buyerName: string | null; remarks: string | null; enteredByName: string | null; approvedByName: string | null; rating: string | null }
interface SupplierDetail { id: string; code: string; name: string; outstandingBalance: number; ledger: LedgerRow[] }
interface OpenPurchase { id: string; purchaseNo: string; dueDate: string | null; outstanding: number; status: 'pending' | 'partial' | 'overdue' }
const { data: suppliers } = await useFetch<Supplier[]>('/api/suppliers')
const selectedSupplierId = ref(''); const detail = ref<SupplierDetail | null>(null); const openPurchases = ref<OpenPurchase[]>([])
const loading = ref(false); const submitting = ref(false); const message = ref(''); const error = ref('')
const form = reactive({ entryDate: new Date().toISOString().slice(0, 10), amount: 0, paymentMode: 'cash', referenceNo: '', remarks: '' })
const allocationAmounts = reactive<Record<string, number>>({})
watch(suppliers, (rows) => { if (!selectedSupplierId.value && rows?.[0]) selectedSupplierId.value = rows[0].id }, { immediate: true })
watch(selectedSupplierId, async (id) => { Object.keys(allocationAmounts).forEach((key) => delete allocationAmounts[key]); if (!id) { detail.value = null; openPurchases.value = []; return }; loading.value = true; try { [detail.value, openPurchases.value] = await Promise.all([$fetch<SupplierDetail>(`/api/suppliers/${id}`), $fetch<OpenPurchase[]>(`/api/suppliers/${id}/open-purchases`)]) } finally { loading.value = false } })
function fmt(value: string | number) { return new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 2 }).format(Number(value)) }
const runningLedger = computed(() => { let balance = 0; return (detail.value?.ledger || []).map((row) => { balance += Number(row.credit) - Number(row.debit); return { ...row, runningBalance: balance } }) })
const allocatedTotal = computed(() => Object.values(allocationAmounts).reduce((total, amount) => total + (Number(amount) || 0), 0))
async function postPayment() { if (!selectedSupplierId.value) return; submitting.value = true; message.value = ''; error.value = ''; try { if (allocatedTotal.value && Math.abs(allocatedTotal.value - form.amount) > 0.005) { error.value = 'Allocated purchase amounts must equal the payment amount.'; return }; const supplierAllocations = Object.entries(allocationAmounts).filter(([, amount]) => Number(amount) > 0).map(([purchaseId, amount]) => ({ purchaseId, amount: Number(amount) })); const result = await $fetch<{ voucherNo: string }>('/api/party-ledger/payments', { method: 'POST', body: { partyType: 'supplier', partyId: selectedSupplierId.value, ...form, supplierAllocations } }); message.value = `${result.voucherNo} posted successfully.`; form.amount = 0; form.referenceNo = ''; form.remarks = ''; Object.keys(allocationAmounts).forEach((key) => delete allocationAmounts[key]); [detail.value, openPurchases.value] = await Promise.all([$fetch<SupplierDetail>(`/api/suppliers/${selectedSupplierId.value}`), $fetch<OpenPurchase[]>(`/api/suppliers/${selectedSupplierId.value}/open-purchases`)]) } catch (requestError: any) { error.value = requestError?.data?.statusMessage || 'Could not post supplier payment.' } finally { submitting.value = false } }
</script>
<template><main><div class="heading"><div><h1>Supplier Ledger</h1><p>Accounts payable linked to Supplier Master. Payments may be allocated to open credit purchases.</p></div><NuxtLink class="link-button" to="/suppliers">Supplier Master</NuxtLink></div><section class="toolbar card"><label>Supplier<select v-model="selectedSupplierId"><option v-for="supplier in suppliers || []" :key="supplier.id" :value="supplier.id">{{ supplier.name }} — {{ supplier.code }}</option></select></label><div v-if="detail" class="balance"><span>Running Balance</span><strong>{{ fmt(detail.outstandingBalance) }}</strong></div></section><form v-if="detail" class="card payment-form" @submit.prevent="postPayment"><h2>Record Supplier Payment</h2><label>Date<input v-model="form.entryDate" type="date" required></label><label>Amount (Rs)<input v-model.number="form.amount" type="number" min="0.01" step="0.01" required></label><label>Payment Mode<select v-model="form.paymentMode"><option value="cash">Cash</option><option value="upi">UPI</option></select></label><label>Reference No<input v-model="form.referenceNo" maxlength="100"></label><label class="wide">Remarks<textarea v-model="form.remarks" maxlength="1000"></textarea></label><div v-if="openPurchases.length" class="allocation wide"><strong>Allocate Payment to Credit Purchases</strong><span>Optional for advances/opening balances. If used, allocations must equal the payment amount.</span><div v-for="purchase in openPurchases" :key="purchase.id" class="allocation-row"><label><input v-model.number="allocationAmounts[purchase.id]" type="number" min="0" :max="purchase.outstanding" step="0.01"> {{ purchase.purchaseNo }} · Due {{ purchase.dueDate || '—' }} · {{ purchase.status }}</label><span>Outstanding {{ fmt(purchase.outstanding) }}</span></div><small>Allocated: {{ fmt(allocatedTotal) }}</small></div><div class="form-actions"><span v-if="message" class="success">{{ message }}</span><span v-if="error" class="error">{{ error }}</span><button :disabled="submitting">{{ submitting ? 'Posting…' : 'Post Payment' }}</button></div></form><div v-if="loading" class="card">Loading ledger…</div><div v-else-if="detail" class="card table"><table><thead><tr><th>Date</th><th>Voucher No</th><th>Purchase No</th><th>Supplier ID</th><th>Supplier Name</th><th>Particulars</th><th>Debit - Payments (Rs)</th><th>Credit - Purchases (Rs)</th><th>Running Balance (Rs)</th><th>Payment Mode</th><th>Reference No</th><th>Due Date</th><th>Status</th><th>Buyer</th><th>Remarks</th><th>Entered By</th><th>Approved By</th><th>Rating</th></tr></thead><tbody><tr v-for="row in runningLedger" :key="row.id"><td>{{ row.entryDate }}</td><td>{{ row.voucherNo }}</td><td>{{ row.purchaseNo || '—' }}</td><td>{{ detail.code }}</td><td>{{ detail.name }}</td><td>{{ row.particulars || '—' }}</td><td>{{ Number(row.debit) ? fmt(row.debit) : '—' }}</td><td>{{ Number(row.credit) ? fmt(row.credit) : '—' }}</td><td>{{ fmt(row.runningBalance) }}</td><td>{{ row.paymentMode || '—' }}</td><td>{{ row.referenceNo || '—' }}</td><td>{{ row.dueDate || '—' }}</td><td>{{ row.status }}</td><td>{{ row.buyerName || '—' }}</td><td>{{ row.remarks || '—' }}</td><td>{{ row.enteredByName || '—' }}</td><td>{{ row.approvedByName || '—' }}</td><td>{{ row.rating || '—' }}</td></tr></tbody></table></div></main></template>
<style scoped>main{max-width:100%}.heading{display:flex;justify-content:space-between;gap:16px}h1{font-size:20px;margin:0 0 4px}.heading p{margin:0;color:var(--color-text-muted);font-size:13px}.link-button,button{padding:8px 12px;background:var(--color-accent);color:#fff;border:0;border-radius:5px;text-decoration:none;cursor:pointer}.toolbar{display:flex;align-items:end;gap:24px;margin-top:16px}.toolbar label{width:360px}label{font-size:12px}input,select,textarea{display:block;width:100%;padding:8px;margin-top:4px;border:1px solid var(--color-border);border-radius:5px;background:var(--color-surface)}.balance{margin-left:auto}.balance span{display:block;font-size:12px;color:var(--color-text-muted)}.balance strong{font-size:20px}.payment-form{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:16px}.payment-form h2,.form-actions{grid-column:1/-1;margin:0}.wide{grid-column:span 2}.allocation{display:grid;gap:8px;padding:10px;border:1px solid var(--color-border);border-radius:5px}.allocation>span,.allocation small{font-size:12px;color:var(--color-text-muted)}.allocation-row{display:flex;justify-content:space-between;gap:12px}.allocation-row label{display:flex;gap:8px;align-items:center}.allocation-row input{width:110px;margin:0}.form-actions{display:flex;gap:12px;align-items:center}.success{color:var(--color-accent)}.error{color:var(--color-danger)}.table{overflow:auto;margin-top:16px}table{min-width:1950px;width:100%;border-collapse:collapse}th,td{padding:8px;text-align:left;white-space:nowrap;border-bottom:1px solid var(--color-border)}th{font-size:12px}</style>
